#include <vector>
#include <cstddef>
#include <cmath>
#include <stdexcept>
#include <algorithm>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) {
        throw std::invalid_argument("b.size() must equal N");
    }

    x.assign(N, 0.0);

    if (N == 0) {
        return;
    }

    // Build a dense augmented matrix [A | b].
    // COO duplicates are accumulated safely with atomics.
    std::vector<double> aug(N * (N + 1), 0.0);

    #pragma omp parallel for schedule(static)
    for (size_t i = 0; i < N; ++i) {
        aug[i * (N + 1) + N] = b[i];
    }

    #pragma omp parallel for schedule(static)
    for (size_t k = 0; k < A.size(); ++k) {
        const COOElement &e = A[k];
        if (e.row >= N || e.column >= N) {
            continue;
        }
        #pragma omp atomic update
        aug[e.row * (N + 1) + e.column] += e.value;
    }

    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting.
    for (size_t col = 0; col < N; ++col) {
        size_t pivot_row = col;
        double max_abs = 0.0;

        // Find pivot row in parallel: each thread keeps a private best, then merge in critical.
        #pragma omp parallel
        {
            size_t local_row = col;
            double local_max = -1.0;

            #pragma omp for nowait
            for (size_t r = col; r < N; ++r) {
                double v = std::fabs(aug[r * (N + 1) + col]);
                if (v > local_max) {
                    local_max = v;
                    local_row = r;
                }
            }

            #pragma omp critical
            {
                if (local_max > max_abs) {
                    max_abs = local_max;
                    pivot_row = local_row;
                }
            }
        }

        if (max_abs < eps) {
            throw std::runtime_error("Matrix is singular or nearly singular");
        }

        if (pivot_row != col) {
            #pragma omp parallel for schedule(static)
            for (size_t j = col; j <= N; ++j) {
                std::swap(aug[col * (N + 1) + j], aug[pivot_row * (N + 1) + j]);
            }
        }

        const double pivot = aug[col * (N + 1) + col];

        // Eliminate below pivot. Each thread updates distinct rows.
        #pragma omp parallel for schedule(static)
        for (size_t r = col + 1; r < N; ++r) {
            double factor = aug[r * (N + 1) + col] / pivot;
            aug[r * (N + 1) + col] = 0.0;
            for (size_t j = col + 1; j <= N; ++j) {
                aug[r * (N + 1) + j] -= factor * aug[col * (N + 1) + j];
            }
        }
    }

    // Back substitution. Parallelize the dot product with a reduction.
    for (ptrdiff_t i = static_cast<ptrdiff_t>(N) - 1; i >= 0; --i) {
        double sum = 0.0;

        #pragma omp parallel for reduction(+:sum) schedule(static)
        for (ptrdiff_t j = i + 1; j < static_cast<ptrdiff_t>(N); ++j) {
            sum += aug[static_cast<size_t>(i) * (N + 1) + static_cast<size_t>(j)] * x[static_cast<size_t>(j)];
        }

        double diag = aug[static_cast<size_t>(i) * (N + 1) + static_cast<size_t>(i)];
        if (std::fabs(diag) < eps) {
            throw std::runtime_error("Matrix is singular or nearly singular during back substitution");
        }

        x[static_cast<size_t>(i)] =
            (aug[static_cast<size_t>(i) * (N + 1) + N] - sum) / diag;
    }
}
